<?php require __DIR__.'/../layout/header.php'; ?><h2>Products</h2><p><a class="button" href="index.php?route=product-form">Add product</a> <a href="index.php?route=cart">Shopping cart</a></p><form method="get"><input type="hidden" name="route" value="products"><input name="q" placeholder="Search name" value="<?=e($search)?>"><input name="category" placeholder="Category" value="<?=e($category)?>"><input name="min" type="number" step=".01" placeholder="Min price"><input name="max" type="number" step=".01" placeholder="Max price"><button>Filter</button></form><label>Live search <input id="liveSearch" placeholder="Type product name..."></label><div id="suggestions"></div><table><tr><th><a href="?route=products&sort=name&dir=ASC">Name ↑</a></th><th>Category</th><th>Price</th><th>Actions</th></tr><?php foreach($rows as $p): ?><tr><td><?=e($p['name'])?></td><td><?=e($p['category'])?></td><td><?=e($p['price'])?></td><td><a href="index.php?route=product-form&id=<?=$p['id']?>">Edit</a><form class="inline" method="post" action="index.php?route=product-delete" onsubmit="return confirm('Delete this product?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="danger">Delete</button></form><form class="inline" method="post" action="index.php?route=cart"><?=csrf_field()?><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="quantity" value="1"><button name="action" value="add">Add to cart</button></form></td></tr><?php endforeach; ?></table><p>Page <?=$page?> of <?=$pages?></p><?php if($page>1): ?><a href="?route=products&page=<?=$page-1?>">Previous</a><?php endif; ?> <?php for($i=1;$i<=$pages;$i++): ?><a href="?route=products&page=<?=$i?>"><?=$i?></a> <?php endfor; ?><?php if($page<$pages): ?><a href="?route=products&page=<?=$page+1?>">Next</a><?php endif; ?><?php require __DIR__.'/../layout/footer.php'; ?>
